param([Parameter(Mandatory=$true)][string]$Session,[switch]$CleanDisposableContainers)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$base="$root/analysis/parallel-aa-receiver";$p="$base/m6-aoa";$clean="$base/clean-receiver";$Session=(Resolve-Path $Session).Path
if(-not$Session.StartsWith([IO.Path]::GetFullPath($base)+[IO.Path]::DirectorySeparatorChar)){throw 'Session outside intended analysis root'}
foreach($snapshot in @('apks-before.json','all-current-apks-before.json','live-reports-before.json','source-tests-before.json')){foreach($f in Get-Content "$Session/$snapshot" -Raw|ConvertFrom-Json){if((Get-FileHash -LiteralPath $f.Path).Hash-ne$f.Hash){throw "Preservation mismatch $($f.Path)"}}}
$first=(Get-Content "$Session/baseline-build-path.txt" -Raw).Trim();$last=(Get-Content "$Session/final-receiver-build-path.txt" -Raw).Trim();$r=Get-Content "$last/build-validation.json" -Raw|ConvertFrom-Json
if($r.DEX_SHA256-ne'2FDBC63F2F9D63B764697D311AF89D460AE6B8E14B0FADABA9C9339F7FE7C235'-or$r.sourceClasses-ne57){throw 'Unexpected receiver change'}
& "$root/scripts/Compare-RdxProtocolBuilds.ps1" -First $first -Second $last -Output "$Session/receiver-reproducibility.json"|Out-Null
function Tree([string]$path){$path=(Resolve-Path $path).Path;return @(Get-ChildItem -LiteralPath $path -Recurse -File|ForEach-Object {$_.FullName.Substring($path.Length)+'='+(Get-FileHash $_.FullName).Hash}|Sort-Object)}
foreach($dir in @('session-transcripts','honda-media-transcripts','video-data-transcripts','secure-body-transcripts')){if(@(Compare-Object (Tree "$first/$dir") (Tree "$last/$dir")).Count){throw 'Receiver transcript mismatch'}}
if(@(Compare-Object (Tree "$Session/baseline-real-tls") (Tree "$Session/final-real-tls")).Count){throw 'Real TLS semantic outputs differ; diagnose rather than claim reproducible'}
function Totals([string]$dir,[string]$tls){$d=[long]0;$a=[long]0;foreach($file in @('test-results.txt','protocol-test-results.txt','independent-test-results.txt','session-test-results.txt','honda-media-test-results.txt','video-data-test-results.txt','secure-body-test-results.txt','api22-provider-model-test-results.txt','api22-shadow-test-results.txt')){$line=Get-Content "$dir/$file" -Tail 1;if($line-notmatch'^RESULT PASS'){throw "Suite failed $file"};$d+=[long]([regex]::Match($line,'\b(?:deterministic|tests)=(\d+)').Groups[1].Value);$a+=[long]([regex]::Match($line,'\bpropertyChecks=(\d+)').Groups[1].Value)};$line=Get-Content "$tls/test-results.txt" -Tail 1;if($line-notmatch'^RESULT PASS'){throw 'TLS suite failed'};$d+=[long]([regex]::Match($line,'\bdeterministic=(\d+)').Groups[1].Value);$a+=[long]([regex]::Match($line,'\bpropertyChecks=(\d+)').Groups[1].Value);return [pscustomobject]@{deterministic=$d;properties=$a}}
$baseline=Totals $first "$Session/baseline-real-tls";$final=Totals $last "$Session/final-real-tls";if($baseline.deterministic-ne$final.deterministic-or$baseline.properties-ne$final.properties){throw 'Baseline/final semantic counts differ'}
$f=Get-Content "$p/FROZEN.json" -Raw|ConvertFrom-Json;if((Get-FileHash (Join-Path $root $f.path)).Hash-ne$f.sha256-or$f.liveExecutionEnabled){throw 'M6 frozen mismatch'}
$static=Get-Content $f.audit -Raw|ConvertFrom-Json;if(-not$static.PASS-or$static.externalAPI22Methods-ne137){throw 'M6 static API audit mismatch'}
$md=[long]([regex]::Match($f.testResult,'deterministic=(\d+)').Groups[1].Value);$mp=[long]([regex]::Match($f.testResult,'propertyChecks=(\d+)').Groups[1].Value)
$edges=[Collections.Generic.HashSet[string]]::new();foreach($t in Get-ChildItem "$($f.build)/transcripts" -File -Filter *.txt|Where-Object Name -ne 'disk-journal.txt'){$before='NEW';foreach($line in Get-Content $t.FullName){$after=$null;if($line.StartsWith('1|')){$parts=$line-split'\|';$after=$parts[5]}elseif($line-match'^state=([A-Z_]+) '){$after=$Matches[1]};if($after-and$after-ne$before){[void]$edges.Add($before+'->'+$after);$before=$after}}}
$edges|Sort-Object|ForEach-Object {$pair=$_-split'->';[pscustomobject]@{before=$pair[0];after=$pair[1];scope='Observed durable/public transcript edge; not exhaustive graph'}}|Export-Csv "$Session/observed-state-edges.csv" -NoTypeInformation
$policy=[ordered]@{schema=1;package=$f.package;apkSHA256=$f.sha256;liveExecutionEnabled=$false;M5requirement='Pinned project review signature + exact frozen M5 identity + strict PASS counts + actual evidence SHA256';permission='Own M6 UID/exact attachment;one normal request if needed;no M5 grant inheritance';allowedAndroidUSB=@('getDeviceList','hasPermission','requestPermission','openDevice','controlTransfer','close');allowedRequests=@(@{type=192;request=51;value=0;index=0;length=2},@{type=64;request=52;value=0;indices=@(0,1,2,3,4,5);maxBytes=256},@{type=64;request=53;value=0;index=0;length=0});forbidden=@('claimInterface','releaseInterface','bulkTransfer','forceClaim','reset','AOA audio/HID','AA protocol','GAL','TLS','MediaCodec','Honda JNI','socket','shell','settings/window mutation');maxStarts=1;maxControlTransfers=8;maxPermissionRequests=1;open='One authorized NORMAL_PHONE only;never accessory';timeoutPolicyMs=@{target=300000;permission=60000;control=1000;detach=10000;reenumeration=15000;total=420000};bounds=@{events=2048;journalRecords=256;journalBytes=131072;devices=32;interfaces=32};causation='Temporal association only; stock Honda may independently act';stateCount=19;normalProgressionEdges=17;observedStateChangingEdges=$edges.Count;runtime='NOT EXECUTED'}
$policy|ConvertTo-Json -Depth 8|Set-Content "$p/M6-LIVE-SAFETY.json"
if($CleanDisposableContainers){$dir=(Resolve-Path "$Session/test-credentials").Path;if(-not$dir.StartsWith($Session+[IO.Path]::DirectorySeparatorChar)){throw 'Unsafe credential cleanup path'};$deleted=@();foreach($file in Get-ChildItem -LiteralPath $dir -File -Filter *.p12){if($file.Name-notin@('root.p12','other-root.p12','root-trust.p12','other-root-trust.p12','client.p12','server.p12','expired.p12','future.p12','other-client.p12')){throw 'Unexpected credential container'};$deleted+=Get-FileHash -LiteralPath $file.FullName;Remove-Item -LiteralPath $file.FullName};if($deleted.Count){[ordered]@{deleted=$deleted;count=$deleted.Count;scope='Fresh disposable desktop TLS fixtures only; preexisting project signing key untouched';secureErasureClaim=$false}|ConvertTo-Json -Depth 5|Set-Content "$Session/credential-cleanup.json"}}
$state=Get-Content "$Session/project-state-before.json" -Raw|ConvertFrom-Json;$state.date='2026-10-25';$state.session=$Session.Substring($root.Length+1);$state.receiver.deterministic=$final.deterministic;$state.receiver.propertyAssertions=$final.properties;$state.receiver.DEXpath=(Join-Path $last 'dex/classes.dex').Substring($root.Length+1);$state.milestones.M6='OFFLINE-PREPARED / LIVE-DISABLED; signed reviewed M5 PASS + separately reviewed activation release + explicit authorization required';$state.milestones.M7='OFFLINE FOUNDATION ONLY; LIVE NOT AUTHORIZED';$state.M6enabled=$false
$state|Add-Member -Force NoteProperty M6 ([ordered]@{artifact=$f;status='OFFLINE-PREPARED / LIVE-DISABLED';deterministic=$md;propertyAssertions=$mp;randomSequences=50000;seed=5563706198314856497;states=19;normalProgressionEdges=17;observedStateChangingEdges=$edges.Count;transcripts=62;independentRequestRows=8;independentDeviceRows=7;permissionStrategy='Separate UID;M6 requests own exact-attachment permission once after reviewed M5 PASS';noActualM5ProofCreated=$true;liveExecuted=$false;AndroidRuntime='UNTESTED';next='M5 RETRY ONLY;no automatic M6 activation'})
$state|Add-Member -Force NoteProperty lastM6SessionSummary ([ordered]@{baseline=$baseline;finalReceiver=$final;M6checks=$md;M6properties=$mp;aggregateChecks=($final.deterministic+$md);aggregateProperties=($final.properties+$mp);priorFrozenCount=110501;countDifference='20 extra certificate/handshake-carrier checks with freshly generated desktop TEST certificates; source/tests/DEX and properties unchanged';historicalAPKs=69;allInitialAPKsPreserved=$true;M4M5reportsPreserved=$true;API22qualifierPreserved=$true;physicalOperations=0;noADB=$true})
$m5line=Get-Content "$Session/m5-host-tool-tests/test-results.txt" -Tail 1;if($m5line-ne'RESULT PASS deterministicChecks=56 propertyChecks=2400000'){throw 'Separate M5 regression not verified'}
$state|Add-Member -Force NoteProperty separateM5Regression ([ordered]@{deterministic=56;propertyAssertions=2400000;existingSequences=20000;seed=5563443368177053746;scope='Existing unchanged M5 pure host suite; not new M6 coverage; no APK rebuild or ADB';result='PASS'})
$state|ConvertTo-Json -Depth 15|Set-Content "$base/PROJECT-STATE.json";$state|ConvertTo-Json -Depth 15|Set-Content "$Session/session-results.json"
Write-Output "M6 OFFLINE FREEZE PASS: receiver $($final.deterministic)/$($final.properties); M6 $md/$mp; states19 normalEdges17 observedEdges$($edges.Count); original69 APKs/live reports/source/tests/qualifier preserved. No ADB/hardware."
